from PIL import Image, ImageFont, ImageDraw
import numpy as np
from collections import deque

im=Image.open('chess_board.png').convert('RGB')
L=np.array([240,217,181]); D=np.array([181,136,99])

def clean(mask,minsize=25):
    h,w=mask.shape
    seen=np.zeros_like(mask,bool)
    out=np.zeros_like(mask,bool)
    for y in range(h):
        for x in range(w):
            if mask[y,x] and not seen[y,x]:
                q=deque([(y,x)]); seen[y,x]=True; comp=[]
                while q:
                    cy,cx=q.popleft(); comp.append((cy,cx))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=cy+dy,cx+dx
                            if 0<=ny<h and 0<=nx<w and mask[ny,nx] and not seen[ny,nx]:
                                seen[ny,nx]=True; q.append((ny,nx))
                if len(comp)>=minsize:
                    for cy,cx in comp: out[cy,cx]=True
    return out

def norm(mask,size=32):
    ys,xs=np.where(mask)
    sub=mask[ys.min():ys.max()+1, xs.min():xs.max()+1]
    return np.array(Image.fromarray((sub*255).astype('uint8')).resize((size,size)))/255.0

def piece_color(a,mask):
    return a[mask].mean()

fonts=['/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
'/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf',
'/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
'/usr/share/fonts/truetype/dejavu/DejaVuSerif-Bold.ttf']
chars={chr(0x265A+i):('B',['k','q','r','b','n','p'][i]) for i in range(6)}
chars.update({chr(0x2654+i):('W',['K','Q','R','B','N','P'][i]) for i in range(6)})
templates={}
for fp in fonts:
    for size in range(40,73,4):
        try: font=ImageFont.truetype(fp,size)
        except: continue
        for ch,(col,name) in chars.items():
            img=Image.new('L',(120,120),0)
            d=ImageDraw.Draw(img)
            d.text((20,20),ch,font=font,fill=255)
            mask=np.array(img)>127
            if mask.sum()<10: continue
            templates.setdefault((col,name),[]).append((fp.split('/')[-1],size,norm(mask)))

squares={}
for r in range(8):
  for c in range(8):
    sq=chr(97+c)+str(8-r)
    base=L if (r+c)%2==0 else D
    a=np.array(im.crop((c*80,r*80,(c+1)*80,(r+1)*80))).astype(int)
    dist=np.abs(a-base).sum(axis=2)
    mask=dist>70
    mask=clean(mask)
    if mask.sum()<50: continue
    v=norm(mask)
    lum=piece_color(a,mask)
    squares[sq]=(v,lum,mask.sum())

for sq in sorted(squares):
    v,lum,n=squares[sq]
    col='B' if lum<130 else 'W'
    scores=[]
    for (tc,name),tl in templates.items():
        if tc!=col: continue
        best=min((np.abs(v-t).mean(),fn,sz) for fn,sz,t in tl)
        scores.append((best[0],name,best[1],best[2]))
    scores.sort()
    print(sq,col,'lum%.0f'%lum,'n%d'%n, ' | '.join('%s %.3f %s %d'%(s[1],s[0],s[2][:8],s[3]) for s in scores[:3]))
